export function parseCsv(text) {
  if (text === undefined || text === null || text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;

  const endField = () => {
    row.push(field);
    field = '';
  };
  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };

  while (i < text.length) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (ch === '"') {
      inQuotes = true;
      i += 1;
      continue;
    }
    if (ch === ',') {
      endField();
      i += 1;
      continue;
    }
    if (ch === '\r') {
      endRow();
      i += text[i + 1] === '\n' ? 2 : 1;
      continue;
    }
    if (ch === '\n') {
      endRow();
      i += 1;
      continue;
    }

    field += ch;
    i += 1;
  }

  // A final line break already pushed the row; do not add an empty one.
  if (field !== '' || row.length > 0) {
    endRow();
  }

  return rows;
}

export function toObjects(rows) {
  if (!rows || rows.length === 0) return [];
  const header = rows[0];
  const objects = [];
  for (let r = 1; r < rows.length; r += 1) {
    const values = rows[r];
    const obj = {};
    for (let c = 0; c < header.length; c += 1) {
      const value = values[c];
      obj[header[c]] = value === undefined ? '' : value;
    }
    objects.push(obj);
  }
  return objects;
}

