import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, toObjects } from '../src/csv.js';

test('empty text gives []', () => {
  assert.deepEqual(parseCsv(''), []);
});

test('simple rows split on commas', () => {
  assert.deepEqual(parseCsv('a,b\nc,d'), [['a', 'b'], ['c', 'd']]);
});

test('quoted field may contain commas', () => {
  assert.deepEqual(parseCsv('a,"b,c",d'), [['a', 'b,c', 'd']]);
});

test('quoted field may contain line breaks', () => {
  assert.deepEqual(parseCsv('a,"b\nc",d'), [['a', 'b\nc', 'd']]);
});

test('doubled quotes inside a quoted field mean one quote', () => {
  assert.deepEqual(parseCsv('a,"he said ""hi""",b'), [['a', 'he said "hi"', 'b']]);
});

test('CRLF line endings', () => {
  assert.deepEqual(parseCsv('a,b\r\nc,d'), [['a', 'b'], ['c', 'd']]);
});

test('a final line break does not add an empty row', () => {
  assert.deepEqual(parseCsv('a,b\n'), [['a', 'b']]);
  assert.deepEqual(parseCsv('a,b\r\n'), [['a', 'b']]);
});

test('empty quoted field is preserved', () => {
  assert.deepEqual(parseCsv('""'), [['']]);
  assert.deepEqual(parseCsv('a,"",b'), [['a', '', 'b']]);
});

test('toObjects keys rows by header', () => {
  assert.deepEqual(toObjects([['name', 'age'], ['ann', '3'], ['bo', '4']]), [
    { name: 'ann', age: '3' },
    { name: 'bo', age: '4' },
  ]);
});

test('toObjects fills short rows with empty strings', () => {
  assert.deepEqual(toObjects([['a', 'b', 'c'], ['1']]), [{ a: '1', b: '', c: '' }]);
});

test('toObjects on empty input gives []', () => {
  assert.deepEqual(toObjects([]), []);
});
